from PIL import Image
import statistics as st

def edges(f):
    px=Image.open(f).convert("RGB").load()
    pbs=[];cbs=[]
    for x in list(range(296,314))+list(range(327,345)):
        c=[sum(px[x,y])/3 for y in range(200,270)]
        # platen bottom: scan down from y=205, transition >115 -> <95
        for i in range(5,len(c)-1):
            if c[i]>115 and c[i+1]<95:
                t=(105-c[i])/(c[i+1]-c[i]); pbs.append(200+i+t); break
        # coil bottom: last dark->light transition before y=265
        for i in range(len(c)-2,5,-1):
            if c[i+1]>=80 and c[i]<75 and c[i-1]<75:
                t=(78-c[i])/(c[i+1]-c[i]); cbs.append(200+i+t); break
    return st.mean(pbs), st.mean(cbs), st.pstdev(pbs), st.pstdev(cbs)

pxmm=55/34.0  # platen 34 mm = 55 px
res={}
for f,F in [("captures/side_001.jpg",0.0),("captures/side_003.jpg",9.41),("captures/side_004.jpg",51.95)]:
    pb,cb,spb,scb=edges(f)
    res[F]=(pb,cb)
    print(f,"F",F,"platen_bot %.2f (sd %.2f) coil_bot %.2f (sd %.2f) L=%.2f px = %.2f mm"%(pb,spb,cb,scb,cb-pb,(cb-pb)/pxmm))

L0=res[0.0][1]-res[0.0][0]
for F in (9.41,51.95):
    L=res[F][1]-res[F][0]
    d=(L0-L)/pxmm
    print("F=",F,"delta_spring=%.3f mm  k=%.2f N/mm"%(d,F/d))
EOF

