from PIL import Image
import statistics as st
def ballbottom(f):
    px=Image.open(f).convert("RGB").load()
    vals=[]
    for x in range(315,326):
        c=[sum(px[x,y])/3 for y in range(150,260)]
        # find lowest row that is darker than 100 with rows above also dark (ball), before bright platen/bg
        # scan down; track last row <95 before a row >100 that persists (platen top or bg)
        bb=None
        for i in range(len(c)-2):
            if c[i]<95 and (c[i+1]>105 and c[i+2]>105):
                bb=150+i+(95-c[i])/(c[i+1]-c[i])
        vals.append(bb)
    vals=[v for v in vals if v]
    return st.mean(vals),st.pstdev(vals)
